import type { Page } from '@playwright/test'
import { test, expect, loadEnergyTables } from './fixtures'
import { createDefaultProject } from '../src/model/defaults'

// Independent analytic data, not generated by the implementation under test.
function expected(x: number, p = [3, 2, 700, .2, .4, 1]) {
  const [area, width, center, background, step, steepness] = p
  return (area / Math.PI) * (width / 2) / ((x - center) ** 2 + (width / 2) ** 2)
    + background + step / 2 * (Math.tanh(steepness * (x - center)) + 1)
}
async function openExample(page: Page) {
  await page.addInitScript(() => Object.defineProperty(window, 'showOpenFilePicker', { value: undefined }))
  await page.goto('/')
  await loadEnergyTables(page)
  const project = createDefaultProject()
  const energy = Array.from({ length: 101 }, (_, i) => 690 + i * .2)
  project.datasets = [{ title: 'line-fit example', comment: '', sourceFile: '', energy: 700, energyShift: 0,
    angularResolution: 0, intensityScale: 1, intensityOffset: 0, qzShift: 0, errorWeight: 1,
    polarization: project.experiment.polarization, active: true,
    columns: { qz: energy.map(() => .02), energy, reflectivity: energy.map(x => expected(x)) } }]
  project.activeDatasetIndex = 0
  project.experiment.energyScan = { ...project.experiment.energyScan, energyMin: 690, energyMax: 710, qz: .02 }
  const chooser = page.waitForEvent('filechooser')
  await page.getByRole('button', { name: 'Open… (Ctrl+O)', exact: true }).click()
  await (await chooser).setFiles({ name: 'line-fit.json', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify(project)) })
  await page.getByRole('button', { name: 'Energy Scan', exact: true }).click()
  await expect(page.getByLabel('Plot axis: energy', { exact: true })).toBeVisible()
  await expect(page.getByLabel('Line-fit source', { exact: true })).toContainText('measured R')
}
async function selectRange(page: Page, low = 689, high = 711) {
  // Restore finite data ranges after deliberately selecting an empty viewport.
  await page.getByRole('button', { name: 'Scale', exact: true }).click()
  await page.getByRole('button', { name: 'Properties', exact: true }).click()
  const dialog = page.getByRole('dialog', { name: 'Plot Properties', exact: true })
  await dialog.getByLabel('X min', { exact: true }).fill(String(low))
  await dialog.getByLabel('X max', { exact: true }).fill(String(high))
  await dialog.getByRole('button', { name: 'Apply', exact: true }).click()
  const select = page.getByRole('button', { name: 'Select Area', exact: true })
  if (await select.getAttribute('aria-pressed') !== 'true') await select.click()
  const bounds = (await page.locator('.plot-panel .u-over').boundingBox())!
  await page.mouse.move(bounds.x + bounds.width * .02, bounds.y + bounds.height * .25)
  await page.mouse.down()
  await page.mouse.move(bounds.x + bounds.width * .98, bounds.y + bounds.height * .25, { steps: 5 })
  await page.mouse.up()
}

test('actual WASM line fit recovers a peak and exports the exact displayed result without project edits', async ({ page, context }) => {
  await context.grantPermissions(['clipboard-read', 'clipboard-write'])
  await openExample(page)
  await selectRange(page)
  await page.getByRole('button', { name: 'Fit Lorentzian+Step', exact: true }).click()
  const status = page.locator('.plot-panel__line-fit-status')
  await expect(status).toContainText('squared error', { timeout: 15000 })
  await expect(page.locator('.plot-panel__legend')).toContainText('Lorentzian+Step fit')
  await page.getByRole('button', { name: 'Line-fit result', exact: true }).click()
  const dialog = page.getByRole('dialog', { name: 'Lorentzian+Step result', exact: true })
  await dialog.getByRole('button', { name: 'Copy fit parameters', exact: true }).click()
  await expect(dialog.getByRole('status')).toHaveText('Line-fit parameters and expressions copied.')
  const text = await page.evaluate(() => navigator.clipboard.readText())
  const parameters = ['A', 'G', 'E', 'M', 'S', 'O'].map(name => Number(text.match(new RegExp(`^${name} = (.+)$`, 'm'))![1]))
  const error = Number(text.match(/^Squared error = (.+)$/m)![1])
  expect(error).toBeLessThan(1e-8)
  expect(parameters[2]).toBeCloseTo(700, 3)
  await dialog.getByRole('button', { name: 'Close', exact: true }).click()
  await page.locator('.plot-panel__export > summary').click()
  await page.getByRole('button', { name: 'Copy data to clipboard', exact: true }).click()
  await expect(page.locator('.plot-panel__export-message')).toHaveText('Diagram data copied.')
  const data = await page.evaluate(() => navigator.clipboard.readText())
  // Clipboard plot data uses unlabeled x/y pairs: simulation, measurement, then fit.
  const lines = data.trimEnd().split('\n'), column = 4
  let compared = 0
  for (const line of lines) {
    const cells = line.split('\t')
    if (!cells[column] || !cells[column + 1]) continue
    const x = Number(cells[column]), y = Number(cells[column + 1])
    expect(Math.abs(y - expected(x, parameters))).toBeLessThanOrEqual(1e-15 + 1e-10 * Math.abs(y))
    compared++
  }
  expect(compared).toBe(101)
  await page.getByRole('button', { name: 'Clear Selected Area', exact: true }).click()
  await expect(page.locator('.plot-panel__legend')).not.toContainText('Lorentzian+Step fit')
  await selectRange(page, 720, 730)
  await page.getByRole('button', { name: 'Fit Lorentzian+Step', exact: true }).click()
  await expect(status).toContainText('no samples')
  await selectRange(page)
  await page.getByRole('button', { name: 'Fit Lorentzian+Step', exact: true }).click()
  await expect(status).toContainText('squared error', { timeout: 15000 })
  await page.getByRole('button', { name: 'Reflectivity', exact: true }).click()
  await expect(page.getByRole('button', { name: 'Line-fit result', exact: true })).toHaveCount(0)
  await expect(page.getByRole('button', { name: 'Undo (Ctrl+Z)', exact: true })).toBeDisabled()
})

test('blocked line fit stops and clearing its selection invalidates outstanding work', async ({ page }) => {
  await page.route('**/assets/worker-*.js', async route => {
    const response = await route.fetch()
    await route.fulfill({ response, body: `${await response.text()}\n const lineHandler = self.onmessage; self.onmessage = event => { if (event.data.kind === 'lineFit') { while (true) {} } lineHandler(event); };` })
  })
  await openExample(page)
  await selectRange(page)
  const fit = page.getByRole('button', { name: 'Fit Lorentzian+Step', exact: true })
  await fit.click()
  await page.getByRole('button', { name: 'Stop line fit', exact: true }).click()
  await expect(page.locator('.plot-panel__line-fit-status')).toHaveText('Line fit stopped.', { timeout: 1000 })
  await fit.click()
  await page.getByRole('button', { name: 'Clear Selected Area', exact: true }).click()
  await expect(page.getByRole('button', { name: 'Stop line fit', exact: true })).toHaveCount(0)
  await expect(page.getByRole('button', { name: 'Line-fit result', exact: true })).toHaveCount(0)
  await expect(fit).toBeDisabled()
  await expect(page.getByRole('button', { name: 'Undo (Ctrl+Z)', exact: true })).toBeDisabled()
})
